    const mapElement=container.querySelector('[data-field-map]');
    if(!opts.geography&&global.SengokuWorldMap?.prepareGeography?.(mapElement,render)===false)return;
    const geography=opts.geography||global.SENGOKU_GEOGRAPHY,groups=groupBases(cache.players,geography?.castles||{},global.SENGOKU_DATA?.castles||[],opts.identity,cache.selectedId,cache.rules),self=cache.players.find(p=>p.playerId===opts.identity?.id&&isHomeTarget(p));
    const mapOptions={stateKey:opts.stateKey+':map:'+String(opts.identity?.id||'guest'),castles:groups,selectedId:targetCastleId(current()),homeId:self?.homeCastleId,clan:'あなたの領地',treaties:{'同盟の領地':1},turn:0,isAdmin:opts.identity?.isAdmin===true,allowRestrictedSelection:true,region:'all',geography,title:'群雄の領地',eyebrow:'SHARED FIELD · JAPAN',countUnit:'拠点',hideRoutes:true,markerSize:48,branches:(parentCurrent()?.branches||[]).map(branch=>({...branch,own:parentCurrent()?.playerId===opts.identity?.id})),onBranchSelect:(_parentId,branchId)=>{cache.selectedBranchId=branchId;cache.tab='base';cache.confirm=null;render();},markerAppearance,legend:{own:'あなた',ally:'同盟',reachable:'出陣可能',other:'ほかの領主'},markerTooltip:marker=>marker.branch?{title:marker.name,description:`支拠点 Lv.${marker.level} · ${marker.fallen?'陥落':marker.building?'普請中':'防衛中'}`,detail:'本城の方位を示す配置です。史実の所在地・距離ではありません。'}:({title:marker.name,description:`表示中：${playerText(marker.displayPlayerName,marker.displayPlayerEvaluation,marker.displayPlayerAppearance,marker.displayPlayerId)} · ${marker.displayLevelLabel||keepLabel(marker)}`,detail:marker.players?.slice(0,5).map(p=>`${playerText(p.name,p.evaluation,p.appearance,p.playerId)}（${keepLabel(p)}）`).join('・')}),onSelect:castleId=>{cache.castleFilter=castleId;cache.selectedBranchId='';cache.query='';cache.filter='all';cache.page=1;cache.tab='base';cache.confirm=null;const occupants=cache.players.filter(p=>targetCastleId(p)===castleId);if(!occupants.some(p=>targetKey(p)===cache.selectedId))cache.selectedId=occupants[0]?targetKey(occupants[0]):'';render();}};
