 const RES={gold:'金銭',rice:'兵糧',wood:'木材',stone:'石材',magatama:'勾玉'},TAB={missions:'任務',army:'編成セット',analysis:'合戦研究',officers:'武将の成長',recap:'留守中の報告',history:'歴代の記録',guide:'初陣ガイド'},STAT={lead:'統率',valor:'武勇',intellect:'知略',politics:'政治'};
