 function recapView(){const g=game(),r=data?.recap;if(!r)return`<p class="progress-intro">前回の確認から1分以上経つと、生産・普請・研究・本拠の変化をまとめて表示します。</p>${button('reload','最新の報告を確認')}<h3>最近の合戦</h3>${reportList(g.state.progress.reports.slice(0,5))}`;return`<p class="progress-intro">${date(r.since)} から ${date(r.until)} の領国の変化です。資源は消費・報酬を含む差し引きです。</p><div class="progress-summary">${Object.entries(r.resources).map(([k,v])=>`<div><span>${RES[k]}</span><b class="${v<0?'progress-loss':'progress-gain'}">${v>=0?'+':''}${num(v)}</b></div>`).join('')}</div><p>本隊の兵：${r.troopDelta>=0?'+':''}${num(r.troopDelta)}人 · 未読のシステム便 ${r.unreadMail}件 · 受取可能な任務 ${num(r.unclaimed)}件</p><h3>留守中の防衛 ${num(r.attackCount)}戦</h3><div class="progress-log">${(r.attacks||[]).map(b=>`<article><b>${esc(b.castleName)} · ${b.held?'防衛成功':'攻撃を受けました'}</b><p>${date(b.at)} · ${esc(b.attackerName)}${global.SengokuPublicCourt?.slot?.(b.attackerPlayerId)||''} · 兵損 ${num(b.lost)}</p></article>`).join('')||'<p>この期間の対人防衛はありません。</p>'}</div>${r.home!==r.oldHome?`<p class="progress-warning">本拠が ${esc(g.data.castles.find(c=>c.id===r.oldHome)?.name||r.oldHome)} から ${esc(g.data.castles.find(c=>c.id===r.home)?.name||r.home)} へ変わりました。</p>`:''}<h3>完成した普請</h3><p>${r.completedBuildings.map(v=>`${esc(g.data.buildings.find(b=>b.id===v.id)?.name||v.id)} Lv.${v.level}`).join(' ／ ')||'この期間に完成した施設はありません。'}</p><p>${(r.completedCastles||[]).map(v=>`${esc(g.data.castles.find(c=>c.id===v.id)?.name||v.id)} 城郭 Lv.${v.level}`).join(' ／ ')}</p><h3>進んだ研究</h3><p>${r.completedResearch.map(v=>`${esc(g.data.techs.find(t=>t.id===v.id)?.name||v.id)} Lv.${v.level}`).join(' ／ ')||'この期間に完成した研究はありません。'}</p><div class="progress-inline">${button('acknowledge','報告を確認しました')}${button('tab','任務の報酬を確認','data-tab="missions"')}${button('mail','システム郵便を開く')}</div><h3>最近の合戦</h3>${reportList(g.state.progress.reports.slice(0,5))}`;}
