  const active=(data.marches?.active||[]).filter(m=>m.status==='marching');if(active.some(m=>String(m.actorPlayerId||m.playerId||'')===String(data.self.playerId||'')))return{ok:false,message:'あなたの部隊が進軍中です。到着と戦果の確定を待ってください。'};if(!data.castles.some(c=>c.mine)&&active.length)return{ok:false,message:'最初の上陸部隊が進軍中です。到着後に次の出陣を選べます。'};
