  for(const troops of counts){if(!Number.isInteger(troops)||troops<100||troops>maximum)continue;const p=battlePreview(data,{...base,troops:String(troops)},now);if(!p.ok)continue;
   candidates.push({ok:true,tactic:tactic.id,tacticName:tactic.name,troops,fromCastleId:source?.id||'',sourceName:p.sourceName,foodCost:p.cost,estimatedLoss:p.lost,winChance:p.win?100:0,deterministic:true,predictedWin:p.win,attackPower:p.attack,defensePower:p.defense,reasons:[`${p.sourceName}から${num(troops)}人で出陣。戦力${num(p.attack)}対${num(p.defense)}を比較しました。`,`この戦場は戦力が守備を上回ると攻略できます。必要物資${num(p.cost)}、予想兵損${num(p.lost)}人です。`,'ほかの同盟の行動で戦況が変わった場合は、出陣前に再確認します。']});
  }
